	else
		local tw = self:Tween(panel, {[LUAOBFUSACTOR_DECRYPT_STR_0("\223\188\209\120\23\239\178\199\125\20\201\175\211\125\3\237\188\192\118\30\254\164", "\112\157\221\178\19")]=1}, 0.15);
